using Tern.App.Commands;
using Tern.App.Editing;

namespace Tern.App.Help;

public sealed record FeatureHelp(string Id, string Name, string Category, string Description, string Prerequisite, string Shortcut, string? LaunchCommandId = null, IReadOnlyList<string>? TutorialSteps = null, string PaletteShortcut = "", string? AdvancedDetails = null, string? MenuPath = null)
{
    public IReadOnlyList<string> Steps => TutorialSteps ??
    [
        $"Before you start: {Prerequisite} This guide never performs actions on your documents.",
        (MenuPath is not null ? $"Choose {MenuPath}.{(Shortcut.Length > 0 ? $" Current shortcut: {Shortcut}." : "") } Alternatively, " : "Open ") + $"Help → Command Palette…{(PaletteShortcut.Length > 0 ? $" ({PaletteShortcut})" : "")} and search for {Name}.",
        Description,
        "Check the result before saving or replacing anything. You can leave this guide, replay it, or select another feature at any time.",
    ];
}
public sealed record Tutorial(string Name, IReadOnlyList<string> Steps, string? LaunchCommandId = null);

/// <summary>Help uses the same command names and effective shortcuts as the application.</summary>
public static partial class FeatureCatalog
{
    public static IReadOnlyList<FeatureHelp> TutorialFeatures => Release104Tutorials.Select((tutorial, index) => new FeatureHelp("tutorial.1.0.4." + index, tutorial.Name,
        "Tutorials", tutorial.Steps[0], "Follow the steps with a practice note. Your notes are never changed by opening help.", "",
        tutorial.LaunchCommandId, tutorial.Steps)).Concat(Release105Tutorials.Select((tutorial, index) => new FeatureHelp("tutorial.1.0.5." + index, tutorial.Name, "Tutorials", tutorial.Steps[0], "Use a practice note. Opening help never edits your files.", "", tutorial.LaunchCommandId, tutorial.Steps)))
        .Concat(Release106Tutorials.Select((tutorial, index) => new FeatureHelp("tutorial.1.0.6." + index, tutorial.Name, "Tutorials", tutorial.Steps[0], "Use a practice note. Opening help never edits your files.", "", tutorial.LaunchCommandId, tutorial.Steps))).ToArray();
    public static bool CanLaunchFromGuide(string? id) => id is CommandIds.Settings or CommandIds.Shortcuts or CommandIds.AIConnections or CommandIds.OpenFolder or CommandIds.OpenFile or CommandIds.OpenUrl or CommandIds.NewFile
        or CommandIds.LibraryFiles or CommandIds.LibraryRecent or CommandIds.LibrarySearch or CommandIds.LibraryBacklinks or CommandIds.LibraryBrokenLinks or CommandIds.LibraryTasks
        or CommandIds.ViewSource or CommandIds.ViewSplit or CommandIds.ViewReading or CommandIds.Find or CommandIds.GoToLine or CommandIds.GoToHeading
        or CommandIds.CreateWorkspace or CommandIds.OpenWorkspace or CommandIds.AskKnowledge or CommandIds.NewFromTemplate;
    public static IReadOnlyList<FeatureHelp> Search(CommandRegistry registry, string? query)
    {
        var words = GuideQuery.Words(query);
        return registry.Commands.Select(c => new FeatureHelp(c.Id, c.Title, c.Category, Explain(c), Prerequisite(c), Gesture.Describe(registry.GetGesture(c.Id)), c.Id, MenuPath: MenuLocation(c)))
            .Concat(Subfeatures)
            .Concat(TutorialFeatures)
            .Select(f => f with { PaletteShortcut = Gesture.Describe(registry.GetGesture(CommandIds.CommandPalette)),
                TutorialSteps = f.TutorialSteps?.Select(step => step.Replace("Ctrl+Shift+Space", WritingShortcut(registry), StringComparison.Ordinal)).ToArray(),
                Description = f.Description.Replace("Ctrl+Shift+Space", WritingShortcut(registry), StringComparison.Ordinal) })
            .Where(f => GuideQuery.Matches($"{f.Name} {f.Category} {f.Description} {f.Prerequisite} {f.AdvancedDetails}", words))
            .OrderBy(f => f.Category, StringComparer.OrdinalIgnoreCase).ThenBy(f => f.Name, StringComparer.OrdinalIgnoreCase).ToArray();
    }

    private static string WritingShortcut(CommandRegistry registry) => Gesture.Describe(registry.GetGesture(CommandIds.AskAI)) is { Length: > 0 } shortcut
        ? shortcut : "Edit → Write with AI";

    private static string MenuLocation(CommandDefinition command)
    {
        var parent = command.Id switch
        {
            CommandIds.FoldSection or CommandIds.MoveSectionUp or CommandIds.MoveSectionDown or CommandIds.PromoteSection or CommandIds.DemoteSection => "Format → Section",
            CommandIds.ClearRecent or CommandIds.RecentlyDiscarded => "File → Open Recent",
            CommandIds.WorkspacePrivacy or CommandIds.ClearFileHistory or CommandIds.ClearWorkspaceHistory => "File → History and recovery → History Privacy",
            CommandIds.ShowHistory or CommandIds.GitDiff or CommandIds.ReloadFromDisk or CommandIds.ReviewSaveFragments => "File → History and recovery",
            CommandIds.ReopenWithEncoding or CommandIds.ChangeEncoding or CommandIds.ChangeLineEnding => "File → Encoding and line endings",
            CommandIds.Rename or CommandIds.MoveDocument or CommandIds.DuplicateDocument or CommandIds.RevealInExplorer => "File → Document actions",
            CommandIds.OpenFolder or CommandIds.OpenWorkspace or CommandIds.CreateWorkspace or CommandIds.PromoteFolder or CommandIds.NewWorkspaceFile or CommandIds.NewFolder or CommandIds.CloseWorkspace or CommandIds.CloseAllWorkspaces => "File → Folders and workspaces",
            CommandIds.Heading1 or CommandIds.Heading2 or CommandIds.Heading3 or CommandIds.HeadingUp or CommandIds.HeadingDown => "Format → Heading",
            CommandIds.InsertTable => "Format → Table",
            _ when TableEditingService.Handles(command.Id) => "Format → Table",
            CommandIds.CommandPalette => "Help",
            CommandIds.Settings or CommandIds.AIConnections => "Edit",
            CommandIds.Exit => "File",
            _ => command.Category switch
            {
                "Library" => "View → Library views",
                "Navigate" => "Go",
                "Workspace" or "File" => "File",
                "Settings" or "Search" => "Edit",
                "App" => "Help",
                "Insert" => "Format",
                _ => command.Category
            }
        };
        return parent + " → " + command.Title;
    }

