        CommandIds.Bold => "Make selected text bold with **double asterisks**. Place the caret or select text, then choose Bold; Undo reverses the markup edit.",
        CommandIds.Italic => "Emphasize selected text with *single asterisks*. Place the caret or select text, then choose Italic.",
        CommandIds.InlineCode => "Mark a short code fragment using backticks, such as `name`. Inline code preserves its literal text instead of applying ordinary emphasis.",
        CommandIds.Strikethrough => "Mark text as crossed out using ~~double tildes~~. Preview support depends on the selected Markdown profile.",
        CommandIds.InsertLink => "Choose Web address, Local file, Heading in this document, or Workspace note. Workspace notes include aliases and headings, emit resolving wiki links, and are also offered when typing [[ in a saved workspace note. Optional link text defaults to the destination. Insert link enables after validation.",
        CommandIds.Heading1 or CommandIds.Heading2 or CommandIds.Heading3 => "Set the line containing the caret (or the start of a selection) to a title, section or subsection heading. Type the heading words after the # marks and check the preview. Undo reverses the edit.",
        CommandIds.HeadingUp => "Make an existing heading larger by removing one #. On a # title, another use returns it to plain text. Place the caret on the heading line first; Undo reverses the edit.",
        CommandIds.HeadingDown => "Make a heading smaller by adding one #, or turn a plain line into a # heading. Place the caret on that line first. The smallest level is ######.",
        CommandIds.ToggleQuote => "Add or remove the > prefix on selected lines to show them as a block quotation.",
        CommandIds.ToggleBullet => "Add or remove an unordered-list marker, such as - item, on selected lines.",
        CommandIds.ToggleNumbered => "Add or remove numbered-list markup on selected lines. The preview displays an ordered list.",
        CommandIds.ToggleTask => "Add or remove task-list markup, such as - [ ] task, on selected lines. Use the task command at the caret to mark a task complete.",
        CommandIds.ToggleTaskAtCaret => "On a task-list line, switch between unchecked [ ] and checked [x]. This edits the Markdown; save explicitly to keep it on disk.",
        _ when c.Category == "Format" => $"Select text or place the caret, then choose {c.Title} to apply the corresponding Markdown markup. Undo reverses the edit.",
        _ when c.Id.StartsWith("view.zoom", StringComparison.Ordinal) => "Change the document text size. Reset returns to the default size.",
        _ => $"Choose {c.Category} → {c.Title} from the menu or command palette. Use the listed shortcut when assigned.",
    };

    public static IReadOnlyList<Tutorial> Tutorials { get; } =
    [
        new("Write your first document", ["You can exit at any time. These instructions never change your documents automatically.", "Close this guide and choose File → New Document. No workspace is required.", "Type # My first note, then a blank line and some text. Split shows the preview beside your source.", "Choose File → Save, select a folder and filename, then save. A changed document displays an unsaved-change indicator.", "Replay this guide from Help whenever you need it."]),
        new("Browse and search a workspace", ["A folder is a physical directory. A workspace is a named persistent context for a folder and its application state. Markdown files stay ordinary files. This guide never creates or removes files.", "Choose File → Folders and workspaces → Open Workspace and select a saved workspace containing Markdown files. Open Folder is the separate plain-directory browser.", "Choose a file in the Library. Quick Open searches filenames; Find in Workspace searches workspace text.", "Close Workspace releases the folder and its documents. Review Save, Discard and Cancel prompts; files remain on disk."]),
        new("Change line endings safely", ["Open a document. Keep a copy if another tool requires a particular format.", "Click LF, CRLF or CR in the status bar, or search Change Line Endings in the command palette.", "Choose LF, CRLF or CR to convert the open text. The conversion does not save yet.", "Choose Save to write the file. Save, Save As and Save All preserve your selected line endings. The separate encoding control determines character encoding."]),
        new("Find features and customize keys", ["Help → Command Palette opens the command palette. Type a feature name and select the desired command.", "Open Help to search feature descriptions and prerequisites, including LF, CRLF and synchronized scrolling.", "Open Keyboard Shortcuts, search a command, select it, press the desired keys and choose Assign.", "If keys are already assigned, review the conflict prompt. Cancel preserves the existing binding. Reset restores defaults."]),
        new("Why use a workspace?", ["A workspace is a named saved context for related files. Open Folder browses a directory without creating workspace metadata. Workspaces are optional: standalone documents still support opening, writing and saving.", "Use a workspace when you want a folder explorer, project-wide text search, backlinks, broken-link checks and unfinished tasks together.", "Choose Open Folder to browse an existing directory, Open Workspace to restore a saved workspace, or Create Workspace for a named new context. Markdown remains ordinary files.", "You may open multiple roots. Switch the active workspace to focus its file tree and search/link graph; open tabs and unsaved text remain intact.", "Close Workspace detaches the selected root after unsaved-change decisions. Close All Workspaces reviews the open roots together; standalone and unnamed documents remain separate."], CommandIds.OpenFolder),
        new("Write without a workspace", ["You do not need a folder project for a single note. Existing open documents are preserved while you follow this lesson.", "Choose File → New Document or Open Files. Type Markdown and use Source, Split or Reading as needed.", "Choose Save and pick the filename and ordinary folder where you want the document. Opening a file does not require attaching that folder as a workspace.", "Add a workspace later if you need its explorer, search, links and tasks. Your document remains an ordinary file."], CommandIds.NewFile),
        new("Open and switch multiple workspaces", ["Use this workflow for separate projects that should keep independent folder trees and search/link graphs.", "Choose Open Workspace for a saved context, or Open Folder to browse an existing directory. Add another root for an independent project; already-open roots are reused.", "Select a workspace or folder in Library. Roots appear as stacked expandable trees, with nested workspaces shown beneath their parents. Expand all and Collapse all apply to Library roots. Switching preserves open tabs and unsaved edits.", "For a new project, choose Create Workspace and enter an unused folder name. Existing folders are opened rather than overwritten.", "Use Close Workspace for the active root or Close All Workspaces for all roots. Review Save, Discard and Cancel for affected documents before detaching anything."], CommandIds.OpenFolder),
        new("Move through Tern with the keyboard", ["Press Tab to move to the next control or Shift+Tab to go back.", "In the main window, use F6 and Shift+F6 to move between visible areas, including the Library, document tabs, Source, Reading, and the selected Inspector tab. In Source, Tab can indent text.", "Use Tab to focus a pane divider and the arrow keys to resize it. In a dialog or Write with AI, Tab and Shift+Tab cycle through that screen.", "In Review AI suggestion, Tab through the Original and Result textboxes, then through Back, Copy result, Apply, and Close. Escape closes the review without applying the suggestion."], CommandIds.Shortcuts),
        new("Navigate and review a note with the Inspector", ["Open a Markdown note containing headings and links.", "In Outline, search for a heading and select it to jump to the section.", "In Links, search by label or destination and select a result to jump to its source line.", "For a saved practice file, make an edit and save in Tern. Open History, choose a dated version to compare, and use Open as copy to open the version in an unsaved tab."], CommandIds.ToggleRightPanel),
        new("Review and apply an AI edit", ["Double-click empty space on the tab bar to create a blank practice note. Open Write with AI and describe the draft you want, or select a paragraph in Source before opening it to try a starter.", "Check what text will be shared and which connection will receive it. Choose Generate for review.", "Compare Original and Result side by side. Use the bottom row to go Back, Copy result, Apply all proposed changes, or Close. Escape also discards the suggestion.", "For a summary, explanation, or task list, Apply inserts the result below the source. Use Undo to restore the original practice text."], CommandIds.AskAI),
        new("Ask your notes a question and verify the answer", ["Set up AI once. If no AI connection exists, Explore your notes opens AI Connections. To change AI later, use the AI button at the top of Tern. Open a workspace with your notes.", "Choose Edit → Explore your notes. Type a question or choose a suggestion, then press Find my notes or Ctrl+Enter. Name the project, person or date for a better result.", "Keep the notes that fit and untick anything private. If Tern asks, choose Yes, use online AI. Press Get my answer. No note text leaves this computer before that.", "Read the answer and open a note under Found in to check important facts. Choose Copy for email, Save as PDF, Add to my note or Print. Tern prepares and checks the full report before showing it as ready. Review its executive summary, detailed findings, exact evidence and final actions. Use Preview report for the formatted full report. If you edit it, press Check report before sharing; this does not export anything. Tick I reviewed this report when it is right. An edit requires a new check; choosing another sharing format reuses the current checked report. If it finds problems, Ask AI to correct these issues requests a checked new draft for you to review; it never exports automatically. Failed or out-of-date corrections keep your edits and issues. Email is built on this computer from that checked report; other formats keep it complete. Switching formats does not send another AI request."], CommandIds.AskKnowledge),
        new("Connect a local Ollama model", ["Prerequisites: a running Ollama server and an installed model. Tern does not download or start models. Opening AI Connections sends nothing.", "Open Settings → AI connections → Manage AI connections. On Choose service, select Ollama (local), then Configure connection. Name the connection and enter the exact installed model name; Advanced shows the local /api/chat endpoint.", "Choose Continue to validation. Read the destination, then Validate connection. This sends a fixed test message to the selected model and displays success or an error; it never sends a note.", "If the server cannot be reached, check that Ollama is running and the endpoint is correct. If the model is unavailable, check its exact installed ID. Save connection stores the settings; saving alone does not test them.", "For a separate question, expand Try your own message (optional), paste a short reviewed message and check consent before Send request. Alternatively choose the saved API connection in the main toolbar for writing.", "Review the response before copying it. Cancel request stops waiting but cannot recall text already received. The scope in Write with AI controls which note text is sent."], CommandIds.AIConnections),
        new("Connect a compatible cloud model", ["Prerequisites: API access, a supported protocol, a permitted model ID and required credentials. A website subscription does not necessarily include API access.", "Open Settings → AI connections → Manage AI connections. Choose a matching service, then Configure connection. Enter a connection name, exact model ID and key. Use Advanced for a documented custom HTTPS endpoint; keep secrets out of URLs.", "Choose Continue to validation and review the service, endpoint and model. Validate connection sends the fixed message Reply with exactly: OK. Provider usage or charges may apply; no document is attached.", "Read the result. Authentication errors require checking the key and API permissions; unavailable-model errors require checking the model ID and account access. For connection failures, check the full endpoint, TLS and network. Correct inputs using Back and validate again.", "Choose Save connection to store metadata and protect the key in Windows Credential Manager. Saving does not send a request and is allowed without validation; an untested saved connection has not been proved to work.", "Reopen and select the saved connection to edit it; Save changes updates it. Back to Choose service provides Delete connection and Create connection. Expand Try your own message (optional) for a separately reviewed question and consent before Send request."], CommandIds.AIConnections),
        new("Save a GitHub Copilot connection", ["Have Copilot access and native copilot.exe installed. Create a personal-account-owned fine-grained GitHub token with Copilot Requests permission; Copilot Chat permission is unnecessary.", "Open AI Connections and select GitHub Copilot in the AI service menu. Selecting a saved connection stays on Choose service. Setup guide opens GitHub's official CLI authentication instructions; choose Configure connection when ready. In Configure, name the connection, enter the token, leave Model at auto for a first test, and confirm the CLI location in Advanced.", "Continue to Validate and save. Validate connection sends a fixed test question using the selected CLI, token and model. Read the success or error; provider usage may apply and no note is attached.", "Save connection stores settings and protects the token in Windows Credential Manager. Next time, select the saved connection. Use New connection or Delete saved connection.", "The saved Copilot connection appears in the main toolbar. Choose Write with AI, enter an instruction, check the scope and destination before Generate for review. Apply the changes you want; Undo restores the draft. The complete Copilot request must fit this connection's Characters to send at one time value and excludes @mentions and CLI commands. For a separate question, use Try connection, review text, check consent and Send reviewed text. Cancel cannot recall text already received."], CommandIds.AIConnections),
        new("Save an MCP tool server", ["Obtain a Streamable HTTP endpoint with MCP 2025-11-25 compatibility and any required bearer token. MCP supplies tools, not an AI model; OAuth and stdio are unsupported.", "Open AI Connections and select MCP server in the AI service menu. Selecting a saved connection stays on Choose service. Setup guide opens the official MCP 2025-11-25 Streamable HTTP specification; choose Configure connection when ready. In Configure, enter a name, full HTTPS endpoint (or HTTP on loopback) and optional bearer token.", "Continue to Validate and save. Connect and discover tools initializes the server and lists tools without calling one. Read any authentication, endpoint or protocol error, then Save connection to store settings and protect the token.", "Select the saved server in the main toolbar and choose Open MCP tools. Opening loads settings without contacting the server; Connect and discover tools explicitly lists tools. In Review tools, read a discovered tool description and schema as untrusted information. Enter the exact JSON object arguments, review their possible external effects, check consent and Run reviewed tool.", "Results are untrusted JSON and never applied to notes automatically. Cancel cannot undo server effects. Reopen a saved connection later; Use New connection or Delete saved connection."], CommandIds.AIConnections),
        new("Manage saved AI and tool connections", ["Open Edit → Settings → AI connections → Manage AI connections. All saved API, GitHub Copilot and MCP profiles share one saved-connections list.", "Choose Create connection and select a type in the AI service menu. Enter only the fields required by that type, then configure, explicitly validate and save. Opening or saving sends nothing.", "Selecting any saved connection stays on Choose service and updates the AI service menu. Choose Configure connection to modify its settings, then validate again and save. Setup guide opens only official service documentation, including GitHub Copilot authentication and the MCP 2025-11-25 Streamable HTTP specification. To remove it, choose Delete connection and review the confirmation; other profiles and notes remain.", "Open the AI entry and select the saved profile. API and Copilot offer Write with AI. The writing panel shows the scope and destination before generation. Applying the suggestion creates an undoable edit.", "MCP offers Open MCP tools instead. Connect and discover tools, choose Review tools, inspect the tool and exact JSON arguments, then consent to Run reviewed tool. Opening tools never sends the note; external tool effects cannot be undone by Tern."], CommandIds.AIConnections),
    ];

    public static IReadOnlyList<Tutorial> TutorialsFor(CommandRegistry registry)
    {
        string Shortcut(string id) => Gesture.Describe(registry.GetGesture(id)) is { Length: > 0 } gesture ? $" Current shortcut: {gesture}." : " This command currently has no keyboard shortcut; use its menu or Help → Command Palette.";
        return Tutorials.Concat(Release104Tutorials).Concat(Release105Tutorials).Concat(Release106Tutorials).Select((tutorial, index) => new Tutorial(tutorial.Name, tutorial.Steps.Select((step, number) => (index, number) switch
        {
            (0, 1) => step + Shortcut(CommandIds.NewFile),
            (0, 3) => step + Shortcut(CommandIds.Save),
            (1, 1) => step + Shortcut(CommandIds.OpenFolder),
            (1, 2) => step + " Quick Open:" + Shortcut(CommandIds.QuickOpen) + " Find in Workspace:" + Shortcut(CommandIds.FindInWorkspace),
            (3, 0) => step + Shortcut(CommandIds.CommandPalette),
            (3, 2) => step + Shortcut(CommandIds.Shortcuts),
            _ => step,
        }).ToArray(), tutorial.LaunchCommandId)).ToArray();
    }

    private static readonly Tutorial[] Release104Tutorials =
    [
        new("Find and reveal matches in every mode", ["Open a practice note containing repeated words. Choose Edit → Find and enter a word.", "Use Source, Split or Reading: matches stay highlighted and the active result is revealed automatically.", "Choose Next or Previous, or select a result. Adjust case, whole-word or regular-expression options when needed.", "For replacements, review the matches before replacing. Undo reverses an applied replacement."], CommandIds.Find),
        new("Export a formatted copy", ["Choose File → Export As… and select HTML, PDF or plain text.", "Set HTML appearance or PDF paper, margins and page numbers, then select Export. Without a destination, Export opens the file picker and continues with the selected separate output. Browse can choose the destination first.", "Open file and Show in folder appear only after a complete successful export. Changing format retains the folder and filename stem, changes the extension, loads that format's saved options and removes the earlier result; changing any export setting also removes completion actions. Export notes start collapsed: expand them before sharing if notes are reported.", "HTML and PDF preserve headings, emphasis, lists, tables, code and permitted images. PDF paginates for paper and rasterizes supported inert SVG badges. Plain text wraps prose, keeps compact tables aligned, turns wide tables into labelled records and collects link destinations in numbered references. Code indentation and Unicode are retained; plain text cannot contain colours, fonts or images."], CommandIds.ExportAs),
        new("Review and print a captured document", ["Choose File → Print Preview… to review the current document snapshot in a larger resizable window.", "Use the page number or previous/next buttons to view actual PDF pages; choose Fit page or a larger zoom to read them.", "Choose All, Current page, or Pages (for example 1-3, 5). Invalid or out-of-range pages block output. Choose Print… to select a printer and copies. Open selected PDF… opens only those pages in a PDF reader instead.", "Changes in the editor do not change an already-open snapshot. Close and reopen the preview to capture newer edits."], CommandIds.Print),
        new("Ask about Tern and recover from connection errors", ["Open Help → Learn Tern… → Ask & learn. Ask naturally, for example: I need to add a new AI connection, how can I do that?", "Help uses the AI chosen in the top AI menu. Choose a text-generation connection there for an AI answer, or use installed offline guides without one. Conversation actions are above the question box. Type in the larger question box and choose Send question. Each question is a fresh request containing your current question and installed guide facts. Earlier questions and answers, notes and selections are not attached. Include the context needed for your question.", "Without a connection, or if the provider fails, Tern automatically displays an installed-guide answer labelled offline. Your question remains available for retry. Answers show formatted headings, lists, code and tables; the newest answer is revealed at the top. The question editor becomes compact to give the answer more reading space. Use Copy conversation or Start new conversation above the question. The Next step strip explains the current action and Learn more opens installed help.", "Recognized Copilot transport failures retry once. Authentication, entitlement and model access require correcting the saved connection or provider account; Tern never changes credentials or account permissions automatically."], CommandIds.Help),
    ];
}
